usage_example:
```hcl
# betterado_release_definition — new stages array syntax
resource "betterado_release_definition" "example" {
  name       = "My Release"
  project_id = var.project_id

  artifact = [
    {
      alias         = "_build"
      source_id     = "${var.project_id}:${var.build_definition_id}"
      type          = "Build"
      is_primary    = true
      is_retained   = false
    }
  ]

  stages = [
    {
      name = "Production"
      rank = 1

      retention_policy = {
        days_to_keep     = 30
        releases_to_keep = 3
        retain_build     = true
      }

      deploy_phase = [
        {
          name       = "Agent job"
          rank       = 1
          phase_type = "agentBasedDeployment"
        }
      ]
    },
    {
      name = "Staging"
      rank = 2

      deploy_phase = [
        {
          name       = "Agent job"
          rank       = 1
          phase_type = "agentBasedDeployment"
        }
      ]
    }
  ]
}

# Enable HCL dynamic expressions — now possible with array syntax
locals {
  stage_names = ["Dev", "QA", "Prod"]
}

resource "betterado_release_definition" "dynamic" {
  name       = "Dynamic Stages"
  project_id = var.project_id

  stages = [
    for idx, name in local.stage_names : {
      name = name
      rank = idx + 1
      deploy_phase = [
        {
          name       = "Agent job"
          rank       = 1
          phase_type = "agentBasedDeployment"
        }
      ]
    }
  ]
}
```
